import * as React from 'react'

import './shine.css'

export type ShineProps = {
    /** Usually a button, link or card. It keeps its own semantics and focus. */
    children: React.ReactNode
    /** Corner radius of the shine's clip, to match the child. */
    radius?: number | string
    /** Colour of the light band. */
    color?: string
    className?: string
}

// A band of light sweeps across the child on hover and on keyboard focus inside.
const Shine = ({ children, radius = 8, color = 'rgba(255, 255, 255, 0.35)', className }: ShineProps) => (
    <span
        className={['rad-fx-shine', className].filter(Boolean).join(' ')}
        style={{ borderRadius: radius, '--rad-fx-shine-color': color } as React.CSSProperties}
    >
        {children}
    </span>
)

export default Shine

.rad-fx-shine {
    position: relative;
    display: inline-flex;
    overflow: hidden;
    isolation: isolate;
}

.rad-fx-shine::after {
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    left: -60%;
    width: 50%;
    pointer-events: none;
    background: linear-gradient(100deg, transparent, var(--rad-fx-shine-color), transparent);
    transform: skewX(-20deg) translateX(0);
}

.rad-fx-shine:hover::after,
.rad-fx-shine:focus-within::after {
    animation: rad-fx-shine 750ms ease-out;
}

@keyframes rad-fx-shine {
    to { transform: skewX(-20deg) translateX(420%); }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-shine::after { display: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-shine::after { display: none; }
